//! Golden tests: holaf-core SPA builders vs the Python-generated fixtures.
//!
//! Fixture file: `tests/fixtures/spa_builders_golden.json`, generated by
//! `tools/export_fixtures.py` from the *real* pure functions of
//! `src/backend/audio_engine.py` / `src/models/strip_model.py` (see its module
//! docstring for the methodology and the two documented divergences: flat
//! Props shape and Rust-style float text).
//!
//! Each fixture case stores the plugin availability set that was used, so the
//! comparison is hermetic: it never depends on which `.so` files happen to be
//! installed on the machine running the tests.

use holaf_core::fx::{self, PluginSet};
use holaf_core::model::{EffectKey, EffectState, Strip, StripType};
use holaf_core::spa::{build_graph_with, build_props_with, control_pairs_with};
use indexmap::IndexMap;
use serde_json::Value;

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/spa_builders_golden.json"
);

fn parse_effect_key(s: &str) -> EffectKey {
    s.parse()
        .expect("fixture effect key must be a valid EffectKey")
}

fn load_fixture() -> Value {
    let text = std::fs::read_to_string(FIXTURE)
        .unwrap_or_else(|e| panic!("cannot read fixture {FIXTURE}: {e}"));
    serde_json::from_str(&text).expect("fixture must be valid JSON")
}

/// Rebuild the exact strip a fixture case describes (only the effects it
/// lists; anything absent behaves like an inactive effect in the builders).
fn build_strip(case: &Value) -> Strip {
    let kind = match case["kind"].as_str().unwrap() {
        "input" => StripType::Input,
        "output" => StripType::Output,
        other => panic!("unknown fixture kind {other:?}"),
    };
    let mut strip = Strip::new("fixture", kind);
    strip.effects.clear();
    if let Value::Object(effects) = &case["effects"] {
        for (name, state) in effects {
            let key = parse_effect_key(name);
            let active = state["active"].as_bool().unwrap();
            let mut params = IndexMap::new();
            for pair in state["params"].as_array().unwrap() {
                let port = pair[0].as_str().unwrap();
                let value = pair[1].as_f64().unwrap() as f32;
                params.insert(port.to_string(), value);
            }
            strip.effects.insert(key, EffectState { active, params });
        }
    }
    strip
}

fn availability(case: &Value) -> PluginSet {
    let files: Vec<String> = case["available"]
        .as_array()
        .unwrap()
        .iter()
        .map(|f| f.as_str().unwrap().to_string())
        .collect();
    PluginSet::from_files(&files)
}

fn pairs(case: &Value) -> Vec<(String, f32)> {
    case["props_pairs"]
        .as_array()
        .unwrap()
        .iter()
        .map(|p| {
            let name = p[0].as_str().unwrap().to_string();
            let value = p[1].as_f64().unwrap() as f32;
            (name, value)
        })
        .collect()
}

#[test]
fn fixture_exists_and_has_expected_cases() {
    let fx = load_fixture();
    let ids: Vec<&str> = fx["cases"]
        .as_array()
        .unwrap()
        .iter()
        .map(|c| c["id"].as_str().unwrap())
        .collect();
    // The representative scenarios from the J2 task.
    for expected in [
        "eq_active_dualmono_input",
        "eq_inactive_dualmono_input",
        "compressor_active_stereo_input",
        "gate_bypassed_eq_active_input",
        "full_input_chain_no_rnnoise",
        "output_chain_eq_tube_comp",
        "noise_cancel_requested_but_missing",
        "noise_cancel_stereo_input",
    ] {
        assert!(ids.contains(&expected), "missing fixture case {expected}");
    }
}

#[test]
fn tables_in_fixture_match_rust_fx_tables() {
    let fx = load_fixture();

    // default_effect_params — every entry byte/order-identical.  Documented
    // divergence: the Python gate table keeps the `'='`-containing
    // "Output select …" key (8 rows); Rust's canonical table omits it because
    // it is always filtered out at SPA-format time (byte output is identical).
    // Only non-`=` ports are therefore compared, positionally.
    for effect in holaf_core::model::EffectKey::all() {
        let name = effect.as_str();
        let rows = &fx["default_effect_params"][name];
        let expected = fx::default_params(effect);
        let rows: Vec<&Value> = rows
            .as_array()
            .unwrap()
            .iter()
            .filter(|r| !r[0].as_str().unwrap().contains('='))
            .collect();
        assert_eq!(rows.len(), expected.len(), "{name}: row count");
        for (i, row) in rows.iter().enumerate() {
            let (port, value) = expected.get_index(i).unwrap();
            assert_eq!(row[0].as_str().unwrap(), port, "{name}[{i}] port");
            assert_eq!(row[1].as_f64().unwrap() as f32, *value, "{name}[{i}] value");
        }
    }

    // bypass_params — compared as a *sorted set* of effective overrides: only
    // a bypass row matters when it changes the default.  This collapses the
    // documented simplifications: Rust's EQ bypass is empty because all 15 flat
    // rows in Python are no-ops over the all-zero defaults, and a compressor
    // `Ratio (1:n) = 1.0` row (present in both) equals its default.  The row
    // order of the bypass table is not semantically significant (values merge
    // by key onto the defaults), and the gate's `'='`-containing
    // "Output select …" row is dropped (filtered at format time).
    for effect in holaf_core::model::EffectKey::all() {
        let name = effect.as_str();
        let rows = &fx["bypass_params"][name];
        let defaults = fx::default_params(effect);
        let expected = fx::bypass_params(effect);
        let mut overrides: Vec<(String, f32)> = Vec::new();
        for row in rows.as_array().unwrap() {
            let port = row[0].as_str().unwrap();
            let value = row[1].as_f64().unwrap() as f32;
            if port.contains('=') {
                continue; // never sent (documented)
            }
            if defaults.get(port) != Some(&value) {
                overrides.push((port.to_string(), value));
            }
        }
        let mut rust_overrides: Vec<(String, f32)> = expected
            .into_iter()
            .filter(|(port, value)| defaults.get(port) != Some(value))
            .map(|(port, value)| (port, value))
            .collect();
        overrides.sort_by(|a, b| a.0.cmp(&b.0));
        rust_overrides.sort_by(|a, b| a.0.cmp(&b.0));
        assert_eq!(
            overrides, rust_overrides,
            "{name} effective bypass overrides"
        );
    }

    // fx_plugin_map rows (key, internal_name, plugin_file, label, stereo).
    let map = fx["fx_plugin_map"].as_array().unwrap();
    assert_eq!(map.len(), 5);
    for row in map {
        let key = parse_effect_key(row[0].as_str().unwrap());
        let spec = fx::plugin_for(key);
        assert_eq!(row[1].as_str().unwrap(), spec.node_label);
        assert_eq!(row[2].as_str().unwrap(), spec.ladspa_file);
        assert_eq!(row[3].as_str().unwrap(), spec.label);
        assert_eq!(row[4].as_bool().unwrap(), spec.stereo);
        // stereo flag agrees with stereo_ports() presence.
        assert_eq!(spec.stereo, spec.stereo_ports().is_some());
    }

    // stereo_plugins port names.
    for (file, ports) in fx["stereo_plugins"].as_object().unwrap() {
        let stereo = fx::plugin_for(match file.as_str() {
            "sc4_1882" => EffectKey::Compressor,
            "librnnoise_ladspa" => EffectKey::NoiseCancel,
            other => panic!("unexpected stereo plugin {other}"),
        })
        .stereo_ports()
        .unwrap();
        assert_eq!(ports["in_l"].as_str().unwrap(), stereo.in_l);
        assert_eq!(ports["in_r"].as_str().unwrap(), stereo.in_r);
        assert_eq!(ports["out_l"].as_str().unwrap(), stereo.out_l);
        assert_eq!(ports["out_r"].as_str().unwrap(), stereo.out_r);
    }
}

#[test]
fn build_graph_matches_python_fixtures_byte_for_byte() {
    let fx = load_fixture();
    for case in fx["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let strip = build_strip(case);
        let avail = availability(case);
        let graph = build_graph_with(&strip, true, &avail);
        let expected = case["graph"].as_str().unwrap();
        assert_eq!(
            graph,
            expected,
            "build_graph mismatch for fixture case {id}\n--- rust ---\n{graph}\n--- python ---\n{expected}"
        );
    }
}

#[test]
fn build_props_matches_flat_python_fixtures_byte_for_byte() {
    let fx = load_fixture();
    for case in fx["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let strip = build_strip(case);
        let avail = availability(case);
        let props = build_props_with(&strip, &avail);
        let expected = case["props_flat"].as_str().unwrap();
        assert_eq!(
            props,
            expected,
            "build_props mismatch for fixture case {id}\n--- rust ---\n{props}\n--- python ---\n{expected}"
        );
    }
}

#[test]
fn control_pairs_match_fixture_pairs() {
    let fx = load_fixture();
    for case in fx["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let strip = build_strip(case);
        let avail = availability(case);
        let got = control_pairs_with(&strip, &avail);
        let expected = pairs(case);
        assert_eq!(
            got, expected,
            "control_pairs mismatch for fixture case {id}"
        );
    }
}

#[test]
fn props_flat_string_derives_from_control_pairs() {
    // Sanity: the SPA-JSON string is a faithful serialisation of the pairs
    // (shortest-f32 values, quoted names) — exactly what the J1 spike sends.
    let fx = load_fixture();
    for case in fx["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let strip = build_strip(case);
        let avail = availability(case);
        let props = build_props_with(&strip, &avail);
        let expected_pairs = pairs(case);
        if expected_pairs.is_empty() {
            assert_eq!(props, "", "case {id}: empty chain must give empty props");
            continue;
        }
        let items: Vec<String> = expected_pairs
            .iter()
            .map(|(n, v)| format!("{n:?} {}", short_f32(*v)))
            .collect();
        let expected_str = format!("{{ \"params\" = [ {} ] }}", items.join(" "));
        assert_eq!(props, expected_str, "case {id}: props must serialize pairs");
    }
}

/// Mirror of the Rust `f32` Display used by the fixture exporter / builder
/// (shortest round-trip, integral floats without trailing `.0`).
fn short_f32(v: f32) -> String {
    format!("{v}")
}
